        return None
    # match forgiving right bounds: positive high clamps to n; very low negative from positive start clamps to start
    if en<st:
        if b.left is not None and b.left>0 and b.right is not None and b.right<0 and en<1:
            en=st
        else:
            raise TucError('Field left value cannot be greater than right value')
    if en>n: en=n
    if en<1: en=1
    if st>en:
        return None
    return list(range(st,en+1))

def complement_bounds(bounds, n):
    out=[]
    for b in bounds:
        inds=bound_indices(b,n)
        if inds is None:
            # mirrors the real program poorly here; use out-of-bounds
            raise TucError(f'Out of bounds: {b.left if b.left is not None else b.raw}')
        if not inds:
            continue
        first=min(inds); last=max(inds)
        comps=[]
        if first>1: comps.append(Bound(1, first-1, None, '', first-1!=1))
        if last<n: comps.append(Bound(last+1, n, None, '', n!=last+1))
        if not comps:
            raise TucError('the complement is empty')
        out.extend(comps)
    return out

def err_oob_raw(b):
    if b.is_range:
        return str(b.left if b.left is not None else (b.right if b.right is not None else b.raw))
    return str(b.left)

def select_bounds(fields, delims, bounds, o, for_json=False):
    n=len(fields)
    # completely empty records are passed through by line-oriented modes
    parts=[]; json_items=[]
    use_bounds=bounds
    if o.complement:
        use_bounds=complement_bounds(bounds,n)
    join_delim = o.replace if o.replace is not None else o.delimiter
    for b in use_bounds:
        try:
            inds=bound_indices(b,n)
        except TucError:
            raise
        if inds is None or len(inds)==0:
            fb=b.fallback if b.fallback is not None else o.fallback
            if fb is not None:
                parts.append(fb); json_items.append(fb); continue
            raise TucError('Out of bounds: '+err_oob_raw(b))
        if for_json:
            for i in inds: json_items.append(fields[i-1])
            continue
        if not b.is_range:
            parts.append(fields[inds[0]-1])
        else:
            st=inds[0]; en=inds[-1]
            seg=[]
            for idx in range(st,en+1):
                seg.append(fields[idx-1])
                if idx<en:
                    d=delims[idx-1] if idx-1 < len(delims) else ''
                    if o.replace is not None:
                        if o.regex is not None:
                            d=o.replace
                        elif o.delimiter!='':
                            d=d.replace(o.delimiter,o.replace)
                    seg.append(d)
            parts.append(''.join(seg))
    if for_json:
        return json_items
    if (o.join is True) or (o.replace is not None):
        return join_delim.join(parts)
    return ''.join(parts)

def process_record_text(rec, spec, o, mode='fields', append_term='\n'):
    # blank records pass through unchanged (newline added by caller)
    if rec=='':
        return ''
    if o.only_delimited:
        if o.regex is not None:
            if not re.search(o.regex, rec): return None
        elif o.delimiter not in rec:
            return None
    fields, delims = split_record(rec,o)
    if o.json:
        if not spec.pure_single:
            die('tuc: runtime error. Cannot format fields when using --json')
        arr=select_bounds(fields,delims,spec.tokens[0][1],o,True)
        return json.dumps(arr, ensure_ascii=False, separators=(',',':'))
    # simple non-format
    if spec.pure_single:
        return select_bounds(fields,delims,spec.tokens[0][1],o,False)
    # formatting. Approximation: render tokens; joins inside placeholders are honored.
    out=[]
    for typ,val in spec.tokens:
        if typ=='lit': out.append(val)
        else: out.append(select_bounds(fields,delims,val,o,False))
    return ''.join(out)

def split_records(data, sep):
    # return text records excluding final artificial empty if data ends with sep; but preserving blank lines
    if data==b'': return []
    chunks=data.split(sep)
    if chunks and chunks[-1]==b'': chunks=chunks[:-1]
    return [to_text(c) for c in chunks]

def process_fields_chars(data,o,spec, chars=False):
    sep=b'\0' if o.zero else b'\n'
    recs=split_records(data,sep)
    out=[]
    term='\0' if o.zero else '\n'
    for rec in recs:
        try:
            if chars:
                # Characters are fields with empty delimiter and no delimiter preservation.
                oo=Opts(**o.__dict__); oo.delimiter=''; oo.regex=None; oo.greedy=False; oo.compress=False; oo.trim=None
                r=process_record_text(rec,spec,oo,'chars',term)
            else:
                r=process_record_text(rec,spec,o,'fields',term)
        except TucError as e:
            sys.stdout.buffer.write(to_bytes(''.join(out))); sys.stdout.buffer.flush()
            die('Error: '+str(e))
        if r is None: continue
        out.append(r+term)
    return to_bytes(''.join(out))

def bytes_fields(data):
    # latin-1 text maps bytes 1:1
    return [chr(b) for b in data]

def process_bytes(data,o,spec):
    fields=bytes_fields(data); delims=['']*(max(0,len(fields)-1))
    if len(fields)==0: return b''
