        if o.json:
            die('tuc: runtime error. --json support is available only for --fields and --characters')
        if not spec.pure_single:
            # format over bytes; preserve bytes via latin-1
            out=[]
            for typ,val in spec.tokens:
                out.append(val if typ=='lit' else select_bounds(fields,delims,val,o,False))
            s=''.join(out)
        else:
            s=select_bounds(fields,delims,spec.tokens[0][1],o,False)
    except TucError as e:
        die('Error: '+str(e))
    return bytes(ord(c) for c in s)

def line_spec_ordered_nonneg(bounds):
    prev=0
    for b in bounds:
        vals=[]
        if b.left is not None: vals.append(b.left)
        if b.right is not None: vals.append(b.right)
        if any(v<0 for v in vals): return False
        start=b.left if b.left is not None else 1
        if start < prev: return False
        prev = b.right if (b.is_range and b.right is not None) else start
    return True

def process_lines(data,o,spec):
    if o.json:
        die('tuc: runtime error. --json support is available only for --fields and --characters')
    sep=b'\0' if o.zero else b'\n'
    term='\0' if o.zero else '\n'
    recs=split_records(data,sep)
    # The real program optimizes only simple ordered positive selections; other line selections act like per-line field cuts.
    if spec.pure_single and not o.complement and line_spec_ordered_nonneg(spec.tokens[0][1]):
        fields=[to_text(r) for r in data.split(sep)]
        if fields and fields[-1]=='': fields=fields[:-1]
        if not fields and data==b'': fields=[]
        delims=[term]*(max(0,len(fields)-1))
        try:
            s=select_bounds(fields,delims,spec.tokens[0][1],o,False)
        except TucError as e:
            die('Error: '+str(e))
        if s=='': return b''
        # Ensure one final line terminator in optimized line mode.
        if not s.endswith(term): s+=term
        return to_bytes(s)
    else:
        # per-line fallback path, delimiter is line separator, each input line is a one-field record
        oo=Opts(**o.__dict__); oo.delimiter=term; oo.regex=None; oo.join=True if o.join is None else o.join
        out=[]
        for rec in recs:
            try:
                r=process_record_text(rec,spec,oo,'fields',term)
            except TucError as e:
                sys.stdout.buffer.write(to_bytes(''.join(out))); sys.stdout.buffer.flush(); die('Error: '+str(e))
            if r is None: continue
            out.append(r+term)
        return to_bytes(''.join(out))

def validate_runtime(o, mode):
    if o.regex is not None:
        if ((o.join is True) and o.replace is None):
            die('tuc: runtime error. Cannot use --regex and --join without --replace-delimiter')
        if o.compress and o.replace is None:
            die('tuc: runtime error. Cannot use --regex and --compress-delimiter without --replace-delimiter')
