def main():
    o=parse_args(sys.argv[1:])
    # No args and no filepath displays intro.
    if not o.any_option and not o.filepath:
        print(INTRO,end=''); return
    data=read_input(o)
    mode,bounds_s=mode_and_bounds(o)
    if mode=='lines' and o.join is None:
        o.join=True
    if o.replace is not None:
        o.join=True
    # --json with bytes/lines rejected by observed behavior; bytes later, lines early.
    try:
        spec=parse_format(bounds_s)
    except ParseError as e:
        die(str(e))
    validate_runtime(o,mode)
    if o.json and mode not in ('fields','chars'):
        die('tuc: runtime error. --json support is available only for --fields and --characters')
    if o.json and not spec.pure_single:
        die('tuc: runtime error. Cannot format fields when using --json')
    if mode=='fields': out=process_fields_chars(data,o,spec,False)
    elif mode=='chars': out=process_fields_chars(data,o,spec,True)
    elif mode=='bytes': out=process_bytes(data,o,spec)
    else: out=process_lines(data,o,spec)
    sys.stdout.buffer.write(out)

if __name__=='__main__':
    try:
        main()
    except BrokenPipeError:
        # Rust binary panics on some broken pipes; exiting quietly is safer for normal use.
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(1)
