class TucError(Exception): pass
class ParseError(Exception): pass

@dataclass
class Bound:
    left: int|None
    right: int|None
    fallback: str|None = None
    raw: str = ''
    is_range: bool = False

@dataclass
class FormatSpec:
    tokens: list  # ('lit', str) or ('bounds', list[Bound])
    pure_single: bool = False

@dataclass
class Opts:
    greedy: bool=False; compress: bool=False; only_delimited: bool=False
    zero: bool=False; complement: bool=False; join: bool|None=None
    json: bool=False; no_mmap: bool=False
    fields: str|None=None; bytes: str|None=None; chars: str|None=None; lines: str|None=None
    delimiter: str='\t'; regex: str|None=None; replace: str|None=None; trim: str|None=None
    fallback: str|None=None; fixed_memory: int|None=None; filepath: str|None=None
    any_option: bool=False

def die(msg, code=1):
    sys.stderr.write(msg+'\n')
    sys.exit(code)

def parse_int(s, whole):
    if s == '':
        raise ParseError(f"failed to parse '{whole}': Field format error: empty field")
    try:
        v=int(s)
    except ValueError:
        raise ParseError(f"failed to parse '{whole}': Not a number `{s}`")
    if v==0:
        raise ParseError(f"failed to parse '{whole}': Zero is not a valid field")
    return v

def parse_one_bound(s, whole=None):
    if whole is None: whole=s
    fb=None
    core=s
    if '=' in s:
        core, fb = s.split('=',1)
    if core=='':
        raise ParseError(f"failed to parse '{whole}': Field format error: empty field")
    if ':' in core:
        parts=core.split(':',1)
        ltxt, rtxt=parts[0], parts[1]
        if ltxt=='' and rtxt=='':
            raise ParseError(f"failed to parse '{whole}': Field format error, no numbers next to `:`")
        left = parse_int(ltxt, whole) if ltxt!='' else None
        right = parse_int(rtxt, whole) if rtxt!='' else None
        if left is not None and right is not None:
            # parser rejects when both textual values are ordered backwards and same sign class
            if (left>0 and right>0 and left>right) or (left<0 and right<0 and left>right):
                raise ParseError(f"failed to parse '{whole}': Field left value cannot be greater than right value")
        return Bound(left,right,fb,core,True)
    else:
        v=parse_int(core, whole)
        return Bound(v,None,fb,core,False)

def parse_bounds_list(s, whole=None):
    if whole is None: whole=s
    if s=='':
        raise ParseError(f"failed to parse '{whole}': Field format error: empty field")
    res=[]
    start=0
    for part in s.split(','):
        if part=='':
            raise ParseError(f"failed to parse '{whole}': Field format error: empty field")
        res.append(parse_one_bound(part, whole))
    return res

def parse_format(s):
    # If no braces, ordinary bounds list.
    if '{' not in s and '}' not in s:
        return FormatSpec([('bounds', parse_bounds_list(s))], pure_single=True)
    tokens=[]; i=0; had_lit=False; had_bounds=0
    while i < len(s):
        if s.startswith('{{', i):
            tokens.append(('lit','{')); had_lit=True; i+=2; continue
        if s.startswith('}}', i):
            tokens.append(('lit','}')); had_lit=True; i+=2; continue
        ch=s[i]
        if ch=='{':
            j=s.find('}', i+1)
            if j<0:
                raise ParseError(f"failed to parse '{s}': Field format error: missing closing parenthesis")
            inner=s[i+1:j]
            if inner=='':
                raise ParseError(f"failed to parse '{s}': Field format error: empty field")
            tokens.append(('bounds', parse_bounds_list(inner, s)))
            had_bounds += 1
            i=j+1
        elif ch=='}':
            raise ParseError(f"failed to parse '{s}': Field format error: missing opening parenthesis")
        else:
            j=i
            while j<len(s) and s[j] not in '{}': j+=1
            tokens.append(('lit', s[i:j])); had_lit=True; i=j
