        # original often panics; a friendly equivalent is acceptable for normal use
        raise ParseError("thread 'main' panicked at src/bounds/userboundslist.rs:50:14:\nUserBoundsList must contain at least one UserBounds")
    pure = (not had_lit and had_bounds==1)
    return FormatSpec(tokens,pure)

def parse_args(argv):
    o=Opts(); files=[]; i=0
