    flags={'-g':'greedy','--greedy-delimiter':'greedy','-p':'compress','--compress-delimiter':'compress','-s':'only_delimited','--only-delimited':'only_delimited','-z':'zero','--zero-terminated':'zero','-m':'complement','--complement':'complement','--json':'json','--no-mmap':'no_mmap'}
    while i < len(argv):
