def mode_and_bounds(o):
    if o.fields is not None: return 'fields', o.fields
    if o.bytes is not None: return 'bytes', o.bytes
    if o.chars is not None: return 'chars', o.chars
    if o.lines is not None: return 'lines', o.lines
    return 'fields', '1:'

def read_input(o):
    if o.filepath:
