def to_text(b):
    return b.decode('utf-8','surrogateescape')

def to_bytes(s):
    return s.encode('utf-8','surrogateescape')

def compress_fixed_delims(s, delim):
    if delim=='': return s
    return re.sub('(?:'+re.escape(delim)+')+', delim, s)

def trim_fixed(s, delim, trim):
    if not trim or delim=='': return s
    pat='(?:'+re.escape(delim)+')+'
    if trim in ('l','L','b','B'):
        s=re.sub('^'+pat, '', s)
    if trim in ('r','R','b','B'):
        s=re.sub(pat+'$', '', s)
    return s

def split_fixed(s, delim, greedy=False):
    fields=[]; delims=[]
    if delim=='':
        fields=[''] + list(s) + ['']
        delims=['']*(len(fields)-1)
        return fields, delims
    i=0; n=len(s); dlen=len(delim)
    while True:
        j=s.find(delim,i)
        if j<0:
            fields.append(s[i:]); break
        fields.append(s[i:j])
        k=j+dlen
        if greedy:
            while s.startswith(delim,k): k+=dlen
        delims.append(s[j:k])
        i=k
    return fields, delims

def split_regex(s, pattern):
    try:
        rx=re.compile(pattern)
    except re.error as e:
        # approximate Rust regex error
        die(f"tuc: runtime error. The regular expression is malformed. regex parse error:\n    {pattern}\n    ^\nerror: {e}")
    fields=[]; delims=[]; last=0
    for m in rx.finditer(s):
        # avoid infinite loops for empty matches: Python advances; keep the delimiter as empty.
        fields.append(s[last:m.start()]); delims.append(s[m.start():m.end()]); last=m.end()
    fields.append(s[last:])
    return fields, delims

def split_record(s, o):
    if o.regex is not None:
        if o.regex.startswith('(?'):
            die(f"tuc: runtime error. The regular expression is malformed. regex parse error:\n    {o.regex}\n    ^^^\nerror: look-around, including look-ahead and look-behind, is not supported")
        return split_regex(s, o.regex)
