def select_bounds(fields, delims, bounds, o, for_json=False):
    n=len(fields)
    # completely empty records are passed through by line-oriented modes
    parts=[]; json_items=[]
    use_bounds=bounds
    if o.complement:
        use_bounds=complement_bounds(bounds,n)
    join_delim = o.replace if o.replace is not None else o.delimiter
    for b in use_bounds:
        try:
            inds=bound_indices(b,n)
        except TucError:
            raise
        if inds is None or len(inds)==0:
            fb=b.fallback if b.fallback is not None else o.fallback
            if fb is not None:
                parts.append(fb); json_items.append(fb); continue
            raise TucError('Out of bounds: '+err_oob_raw(b))
        if for_json:
            for i in inds: json_items.append(fields[i-1])
            continue
        if not b.is_range:
            parts.append(fields[inds[0]-1])
