def process_record_text(rec, spec, o, mode='fields', append_term='\n'):
    # blank records pass through unchanged (newline added by caller)
    if rec=='':
        return ''
    if o.only_delimited:
        if o.regex is not None:
            if not re.search(o.regex, rec): return None
