def split_records(data, sep):
    # return text records excluding final artificial empty if data ends with sep; but preserving blank lines
    if data==b'': return []
    chunks=data.split(sep)
    if chunks and chunks[-1]==b'': chunks=chunks[:-1]
    return [to_text(c) for c in chunks]

def process_fields_chars(data,o,spec, chars=False):
